import type { StaticImageData } from "next/image";
import unsplashPhotos from "./unsplash-photos.json";

// Photography for each image slot. Kept apart from the content files so the
// Proxy (which imports treatments.ts) never bundles images.
//
// Slots are filled from Unsplash (see unsplash-photos.json, generated by
// scripts/unsplash). Unsplash's API guidelines require hotlinking: these photos
// load from images.unsplash.com and every photographer is credited (/credits).
// Local photos (e.g. the clinic's own shoot) can replace any slot with
// { kind: "local", src: importedImage, alt }.

type Credit = { name: string; profile: string; page: string };

export type Photo =
  | { kind: "local"; src: StaticImageData; alt: string; position?: string }
  | {
      kind: "unsplash";
      id: string;
      raw: string;
      width: number;
      height: number;
      color: string;
      alt: string;
      position?: string;
      credit: Credit;
    };

// Keys: "hero", a treatment slug, a journal slug, "salon", "salon-hair",
// "salon-nails" or "branch-<slug>".
export const photos: Partial<Record<string, Photo>> = Object.fromEntries(
  Object.entries(unsplashPhotos).map(([slot, p]) => [slot, { kind: "unsplash" as const, ...p }]),
);

// Unsplash serves resized images through URL parameters on the raw URL.
export const unsplashSrc = (raw: string, width: number) => `${raw}&w=${width}&q=75&auto=format&fit=max`;

// Unsplash asks that links back carry these referral parameters.
export const withReferral = (url: string) => `${url}?utm_source=vo2_website&utm_medium=referral`;
